CREATE TABLE IF NOT EXISTS mail_oauth_states(state_hash text PRIMARY KEY,user_id text NOT NULL,workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,account_id uuid NOT NULL REFERENCES records(id) ON DELETE CASCADE,provider text NOT NULL,verifier text NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS oauth_clients(client_id text PRIMARY KEY, name text NOT NULL, redirect_uris text[] NOT NULL, created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS oauth_codes(code_hash text PRIMARY KEY,client_id text NOT NULL REFERENCES oauth_clients(client_id), user_id text NOT NULL,workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,redirect_uri text NOT NULL,challenge text NOT NULL,scopes text[] NOT NULL,expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS oauth_tokens(token_hash text PRIMARY KEY,client_id text NOT NULL REFERENCES oauth_clients(client_id),user_id text NOT NULL,workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,scopes text[] NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS billing_accounts(workspace_id uuid PRIMARY KEY REFERENCES workspaces(id) ON DELETE CASCADE,customer_id text UNIQUE,subscription_id text,status text NOT NULL DEFAULT 'inactive',credits bigint NOT NULL DEFAULT 0,updated_at timestamptz DEFAULT now());
ALTER TABLE billing_accounts ADD COLUMN IF NOT EXISTS account_limit integer NOT NULL DEFAULT 3;
CREATE TABLE IF NOT EXISTS stripe_events(id text PRIMARY KEY,created_at timestamptz DEFAULT now());
